package com.smartexam.controller;
import com.smartexam.common.ApiResponse; import com.smartexam.common.ErrorCode; import com.smartexam.dto.LoginRequest; import com.smartexam.dto.ChangePasswordRequest; import com.smartexam.dto.StudentRegistrationRequest; import com.smartexam.entity.Users; import com.smartexam.security.JwtService; import com.smartexam.service.UsersService; import com.smartexam.service.AccountLifecycleService; import com.smartexam.service.StudentRegistrationService; import com.smartexam.vo.LoginVO; import com.smartexam.vo.UserVO; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final UsersService users; private final PasswordEncoder encoder; private final JwtService jwt; private final AccountLifecycleService lifecycle; private final StudentRegistrationService registration;
 public AuthController(UsersService users,PasswordEncoder encoder,JwtService jwt,AccountLifecycleService lifecycle,StudentRegistrationService registration){this.users=users;this.encoder=encoder;this.jwt=jwt;this.lifecycle=lifecycle;this.registration=registration;}
 @PostMapping("/register/student") public ApiResponse<UserVO> registerStudent(@Valid @RequestBody StudentRegistrationRequest request){return ApiResponse.success("注册成功，请使用学号和密码登录",registration.register(request));}
 @PostMapping("/login") public ResponseEntity<ApiResponse<LoginVO>> login(@Valid @RequestBody LoginRequest request){Users u=users.findByUsername(request.username());if(u==null||!encoder.matches(request.password(),u.getPasswordHash()))return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(ApiResponse.failure("用户名或密码错误",ErrorCode.UNAUTHORIZED.name()));if(!Integer.valueOf(1).equals(u.getStatus()))return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(ApiResponse.failure("账号已停用，请联系管理员",ErrorCode.ACCOUNT_DISABLED.name()));return ResponseEntity.ok(ApiResponse.success(new LoginVO(jwt.generate(u),UserVO.from(u))));}
 @GetMapping("/me") public ApiResponse<UserVO> me(Authentication auth){Users u=users.findByUsername(auth.getName());return ApiResponse.success(UserVO.from(u));}
 @PutMapping("/password") public ApiResponse<Void> changePassword(Authentication auth,@Valid @RequestBody ChangePasswordRequest request){lifecycle.changePassword(auth.getName(),request);return ApiResponse.success(null);}
}
